// OB1: Главный циклический блок управления (10 мс)
IF "Line_Params".Line_Enable THEN
    "Line_Params".Target_Speed := 3500.0;
    "FC1_SpeedLimiter"();
    "FC2_LadderSafety"();
ELSE
    "Line_Params".Target_Speed := 0.0;
END_IF;

// FC1: Ограничение максимальной скорости
IF "Line_Params".Target_Speed > 3000.0 THEN
    "Line_Params".Target_Speed := 3000.0;
END_IF;

{
  "rungs": [
    {
      "id": "r1",
      "title": "Цепь 1: Контроль предельной уставки и выставление кода 101",
      "elements": [
        {
          "id": "e1",
          "type": "NO",
          "operand1": "\"Line_Params\".Line_Enable"
        },
        {
          "id": "e2",
          "type": "CMP_GE",
          "operand1": "\"Line_Params\".Target_Speed",
          "operand2": "3000.0"
        },
        {
          "id": "e3",
          "type": "ADD",
          "operand1": "100",
          "operand2": "1",
          "operand3": "\"Line_Params\".Error_Code"
        }
      ]
    },
    {
      "id": "r2",
      "title": "Цепь 2: Сброс кода аварии при штатном останове линии",
      "elements": [
        {
          "id": "e4",
          "type": "NC",
          "operand1": "\"Line_Params\".Line_Enable"
        },
        {
          "id": "e5",
          "type": "SUB",
          "operand1": "0",
          "operand2": "0",
          "operand3": "\"Line_Params\".Error_Code"
        }
      ]
    }
  ]
}
